sample:
# state はコードと実リソースの対応表。apply のたびに更新されます。
# この2つのリソースは state に「型.名前」のアドレスで記録されます。
resource "terraform_data" "app" {
  input = "app-server"
}

resource "terraform_data" "db" {
  input = "db-server"
}

# terraform state list で見えるアドレスのイメージ
output "state_addresses" {
  value = join(", ", ["terraform_data.app", "terraform_data.db"])
}

# state が管理しているリソース数(state を手で消すとこの対応が失われます)
output "managed_count" {
  value = 2
}

exercise.starter:
# state list の結果を locals で再現します
locals {
  addresses = [
    # ここにアドレスを書く
  ]
}

exercise.answer:
# state list に並ぶのは「型.名前」のアドレスです。実物の state は
# 手で消したり直接編集したりせず、state list / state show で読むのが安全です。
locals {
  addresses = [
    "aws_ecs_service.api",
    "aws_iam_role.task",
    "aws_s3_bucket.logs",
  ]
}

# sort で並びを固定してから join で1本の文字列にします
output "addresses" {
  value = join(", ", sort(local.addresses))
}

output "resource_count" {
  value = length(local.addresses)
}
